import React, { useState, useEffect } from 'react';
import { Lock, LogOut, Settings, Newspaper, MessageSquare, FileText, Plus, Trash2, Edit2, Save, Image as ImageIcon, Briefcase, List, AlertCircle, User, ArrowUp, ArrowDown, Video, Facebook, Instagram, Youtube, Link as LinkIcon, Bell, Phone, Mail, MapPin, ArrowLeft } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { DEFAULT_CONTACT_INFO } from '../constants';
import { UserRole, NewsItem, EventType, Question, ContactInfo, ProtocolAlert, TeamMember, Step, PopupConfig, QuickLink } from '../types';
import { getNews, saveNews, getEvents, saveEvents, addEvent, deleteEvent, getContactInfo, saveContactInfo, authenticateUser, getPopups, savePopups, getQuickLinks, saveQuickLinks } from '../services/dataService';

// Image compression utility to avoid localStorage quota issues
const compressImage = (base64Str: string, maxWidth = 800, maxHeight = 600): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Str;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }
      } else {
        if (height > maxHeight) {
          width *= maxHeight / height;
          height = maxHeight;
        }
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', 0.7)); // Compress to 70% quality JPEG
    };
    img.onerror = () => resolve(base64Str); // Fallback to original if error
  });
};

const AdminLogin: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentRole, setCurrentRole] = useState<UserRole>('USER');
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<'news' | 'protocols' | 'config'>('news');
  const [news, setNews] = useState<NewsItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [contactInfo, setContactInfo] = useState<ContactInfo>(DEFAULT_CONTACT_INFO);
  const [popups, setPopups] = useState<PopupConfig[]>([]);
  const [quickLinks, setQuickLinks] = useState<QuickLink[]>([]);

  const [isEditingNews, setIsEditingNews] = useState(false);
  const [currentNews, setCurrentNews] = useState<Partial<NewsItem>>({});

  const [isEditingProtocol, setIsEditingProtocol] = useState(false);
  const [currentProtocol, setCurrentProtocol] = useState<Partial<EventType>>({ baseSteps: [], questions: [], alerts: [] });

  const [isEditingPopup, setIsEditingPopup] = useState(false);
  const [currentPopup, setCurrentPopup] = useState<Partial<PopupConfig>>({ title: '', content: '', type: 'info', isEnabled: true });

  const [newMember, setNewMember] = useState<Partial<TeamMember>>({ name: '', role: '' });
  const [newQuickLink, setNewQuickLink] = useState<Partial<QuickLink>>({ title: '', url: '', isEnabled: true });

  useEffect(() => {
    const storedRole = localStorage.getItem('sepri_user_role');
    if (storedRole && (storedRole === 'ADMIN' || storedRole === 'CREATOR')) {
      setIsLoggedIn(true);
      setCurrentRole(storedRole as UserRole);
      loadData();
    }
  }, []);

  const loadData = async () => {
    setNews(await getNews());
    setEvents(await getEvents());
    setPopups(await getPopups());
    setQuickLinks(await getQuickLinks());
    const contact = await getContactInfo();
    if(contact) setContactInfo(contact);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const role = await authenticateUser(email, password);
    if (role) {
        localStorage.setItem('sepri_user_role', role);
        setCurrentRole(role);
        setIsLoggedIn(true);
        loadData();
    } else {
        alert("Credenciales incorrectas.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('sepri_user_role');
    setIsLoggedIn(false);
    navigate('/');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'news' | 'protocol' | 'logo' | 'member', memberId?: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const rawResult = reader.result as string;
        // Compress image before saving to state to prevent localStorage quota errors
        const result = await compressImage(rawResult);

        if (target === 'news') setCurrentNews(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'protocol') setCurrentProtocol(prev => ({ ...prev, imageUrl: result }));
        else if (target === 'logo') setContactInfo(prev => ({ ...prev, logoUrl: result }));
        else if (target === 'member' && !memberId) setNewMember(prev => ({ ...prev, imageUrl: result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveConfig = async () => {
    try {
      await saveContactInfo(contactInfo);
      await saveQuickLinks(quickLinks);
      // Nota: Popups ahora se guardan por separado, pero mantenemos esta llamada por si hay cambios en popups pendientes
      await savePopups(popups); 
      alert("Configuración general guardada correctamente.");
    } catch (e) {
      alert("Error al guardar la configuración.");
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.role) return;
    const member: TeamMember = {
      id: `member-${Date.now()}`,
      name: newMember.name!,
      role: newMember.role!,
      imageUrl: newMember.imageUrl,
      order: contactInfo.teamMembers?.length || 0
    };
    setContactInfo(prev => ({ ...prev, teamMembers: [...(prev.teamMembers || []), member] }));
    setNewMember({ name: '', role: '' });
  };

  const handleRemoveMember = (id: string) => {
    setContactInfo(prev => ({ ...prev, teamMembers: prev.teamMembers?.filter(m => m.id !== id) }));
  };

  // Popup Management
  const handleSavePopup = async () => {
    if (!currentPopup.title?.trim() || !currentPopup.content?.trim()) {
      alert("El título y contenido del aviso son obligatorios.");
      return;
    }

    try {
      let updatedPopups: PopupConfig[] = [];

      if (currentPopup.id) {
        updatedPopups = popups.map(p => p.id === currentPopup.id ? { ...p, ...currentPopup } as PopupConfig : p);
      } else {
        const newP: PopupConfig = {
          id: `popup-${Date.now()}`,
          title: currentPopup.title!,
          content: currentPopup.content!,
          type: (currentPopup.type as any) || 'info',
          isEnabled: true
        };
        updatedPopups = [...popups, newP];
      }

      await savePopups(updatedPopups);

      setPopups(updatedPopups);
      setIsEditingPopup(false);
      setCurrentPopup({ title: '', content: '', type: 'info', isEnabled: true });

      alert(currentPopup.id ? "Aviso actualizado correctamente." : "Aviso creado exitosamente.");
    } catch (error) {
      console.error("Error al guardar popup:", error);
      alert("Error al guardar el aviso en el servidor. Intente de nuevo.");
    }
  };

  const handleTogglePopup = async (id: string) => {
    const updated = popups.map(p => p.id === id ? { ...p, isEnabled: !p.isEnabled } : p);
    try {
      await savePopups(updated);
      setPopups(updated);
    } catch (e) {
      alert("Error al cambiar el estado del aviso.");
    }
  };

  const handleRemovePopup = async (id: string) => {
    if (!confirm("¿Eliminar este aviso definitivamente?")) return;
    const updated = popups.filter(p => p.id !== id);
    try {
      await savePopups(updated);
      setPopups(updated);
    } catch (e) {
      alert("Error al eliminar el aviso.");
    }
  };

  // Quick Links Management
  const handleAddQuickLink = () => {
    if (!newQuickLink.title || !newQuickLink.url) return;
    const link: QuickLink = {
      id: `ql-${Date.now()}`,
      title: newQuickLink.title!,
      url: newQuickLink.url!,
      isEnabled: true
    };
    setQuickLinks([...quickLinks, link]);
    setNewQuickLink({ title: '', url: '' });
  };

  const handleToggleQuickLink = (id: string) => {
    setQuickLinks(quickLinks.map(l => l.id === id ? { ...l, isEnabled: !l.isEnabled } : l));
  };

  const handleRemoveQuickLink = (id: string) => {
    setQuickLinks(quickLinks.filter(l => l.id !== id));
  };

  const handleSaveNews = async () => {
    if (!currentNews.title?.trim() || !currentNews.summary?.trim()) {
      alert("El título y el resumen de la noticia son campos obligatorios.");
      return;
    }

    try {
      let updatedNewsList: NewsItem[] = [];

      if (currentNews.id) {
        updatedNewsList = news.map(n => 
          n.id === currentNews.id 
            ? { ...n, ...currentNews } as NewsItem 
            : n
        );
      } else {
        const newItem: NewsItem = {
          id: Date.now().toString(),
          title: currentNews.title!,
          summary: currentNews.summary!,
          category: (currentNews.category as any) || 'Novedad',
          date: new Date().toLocaleDateString('es-CO'),
          imageUrl: currentNews.imageUrl
        };
        updatedNewsList = [newItem, ...news];
      }

      await saveNews(updatedNewsList);

      setNews(updatedNewsList);
      setIsEditingNews(false);
      setCurrentNews({});

      alert(currentNews.id ? "Noticia actualizada correctamente." : "Noticia publicada correctamente.");
    } catch (error: any) {
      console.error("Error al guardar noticia:", error);
      if (error.message === 'quota') {
        alert("Error: Límite de almacenamiento excedido. Intente usar imágenes más pequeñas.");
      } else {
        alert("No se pudieron guardar los cambios. Verifique su conexión o intente de nuevo.");
      }
    }
  };

  const handleDeleteNews = async (id: string) => {
    if (!confirm("¿Eliminar noticia?")) return;
    const updated = news.filter(n => n.id !== id);
    await saveNews(updated);
    setNews(updated);
  };

  const handleSaveProtocol = async () => {
    if (!currentProtocol.title?.trim() || !currentProtocol.description?.trim()) {
      alert("Título y descripción requeridos");
      return;
    }

    try {
      const protocolToSave: EventType = {
        id: currentProtocol.id || `evt-${Date.now()}`,
        title: currentProtocol.title!,
        description: currentProtocol.description!,
        iconName: currentProtocol.iconName || 'FileText',
        imageUrl: currentProtocol.imageUrl,
        documentUrl: currentProtocol.documentUrl,
        baseSteps: (currentProtocol.baseSteps || []).map((s, i) => ({ ...s, order: i })),
        questions: currentProtocol.questions || [],
        alerts: currentProtocol.alerts || []
      };

      if (currentProtocol.id) {
        const updatedEvents = events.map(e => e.id === currentProtocol.id ? protocolToSave : e);
        await saveEvents(updatedEvents);
        setEvents(updatedEvents);
      } else {
        await addEvent(protocolToSave);
        setEvents(await getEvents());
      }

      setIsEditingProtocol(false);
      setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] });

      alert("Protocolo guardado exitosamente.");
    } catch (error) {
      console.error("Error al guardar protocolo:", error);
      alert("Error al guardar los cambios. Intente de nuevo.");
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-sepri-dark flex flex-col items-center justify-center p-4 relative">
        <div className="absolute top-6 left-6">
          <Link to="/" className="text-white/70 hover:text-white flex items-center gap-2 font-bold transition-colors">
            <ArrowLeft size={20} /> Volver al inicio
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-fade-in-up">
          <div className="text-center mb-8">
            <Settings className="w-12 h-12 text-sepri-yellow mx-auto mb-2" />
            <h1 className="text-2xl font-bold text-sepri-dark">Acceso Administrativo</h1>
          </div>
          <div className="space-y-4">
            <input 
              type="email" 
              placeholder="Email" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Contraseña" 
              className="w-full border p-3 rounded-lg outline-none focus:ring-2 focus:ring-sepri-medium" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
            />
            <button 
              type="submit" 
              className="w-full bg-sepri-medium text-white p-3 rounded-lg font-bold hover:bg-sepri-dark transition-colors shadow-lg"
            >
              Entrar al Panel
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-sepri-dark text-white p-6 hidden md:block">
        <div className="flex items-center gap-3 mb-8">
          <Settings className="text-sepri-yellow" />
          <h1 className="font-bold text-lg">Panel SEPRI</h1>
        </div>
        <nav className="space-y-2">
          <button onClick={() => setActiveTab('news')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'news' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Newspaper size={18} /> Noticias</button>
          <button onClick={() => setActiveTab('protocols')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'protocols' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Briefcase size={18} /> Protocolos</button>
          <button onClick={() => setActiveTab('config')} className={`w-full text-left p-3 rounded flex items-center gap-3 ${activeTab === 'config' ? 'bg-sepri-medium' : 'hover:bg-gray-800'}`}><Settings size={18} /> Configuración</button>
        </nav>
        <button onClick={handleLogout} className="mt-8 text-red-400 flex items-center gap-2 hover:text-red-300 px-3"><LogOut size={18} /> Salir</button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {/* News Tab */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Noticias</h2>
               <button onClick={() => { setCurrentNews({}); setIsEditingNews(true); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg flex items-center gap-2 shadow hover:bg-sepri-dark">
                  <Plus size={18} /> Nueva Noticia
               </button>
            </div>
            {isEditingNews && (
              <form 
                onSubmit={(e) => { e.preventDefault(); handleSaveNews(); }}
                className="bg-white p-6 rounded-xl shadow border animate-fade-in"
              >
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <input 
                      type="text" 
                      placeholder="Título" 
                      className="w-full border p-2 rounded focus:ring-2 focus:ring-sepri-medium outline-none" 
                      value={currentNews.title || ''} 
                      onChange={e => setCurrentNews(prev => ({...prev, title: e.target.value}))} 
                      required
                    />
                    <select 
                      className="border p-2 rounded" 
                      value={currentNews.category || 'Novedad'} 
                      onChange={e => setCurrentNews(prev => ({...prev, category: e.target.value as any}))}
                    >
                       <option value="Novedad">Novedad</option>
                       <option value="Evento">Evento</option>
                       <option value="Importante">Importante</option>
                    </select>
                 </div>
                 <textarea 
                   placeholder="Resumen de la noticia..." 
                   className="w-full border p-2 rounded mb-4 focus:ring-2 focus:ring-sepri-medium outline-none" 
                   rows={6} 
                   value={currentNews.summary || ''} 
                   onChange={e => setCurrentNews(prev => ({...prev, summary: e.target.value}))} 
                   required
                 />

                 {/* Preview and Upload Section */}
                 <div className="flex items-center gap-6 mb-6 p-4 bg-gray-50 rounded-lg border border-dashed">
                    <div className="w-24 h-24 bg-white border rounded overflow-hidden flex-shrink-0 flex items-center justify-center">
                       {currentNews.imageUrl ? (
                          <img src={currentNews.imageUrl} className="w-full h-full object-cover" alt="Preview" />
                       ) : (
                          <ImageIcon className="text-gray-300" size={32} />
                       )}
                    </div>
                    <div className="flex flex-col gap-2">
                       <p className="text-xs font-bold text-gray-500 uppercase tracking-tight">Imagen de Noticia</p>
                       <label className="bg-white border border-gray-300 px-4 py-2 rounded-lg cursor-pointer text-xs font-bold hover:bg-gray-100 transition-colors shadow-sm inline-block">
                          {currentNews.imageUrl ? "Cambiar Imagen" : "Subir Imagen"}
                          <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'news')} />
                       </label>
                       <p className="text-[10px] text-gray-400 italic">Las imágenes se comprimen automáticamente para ahorrar espacio.</p>
                    </div>
                 </div>

                 <div className="flex gap-4">
                    <button 
                      type="submit" 
                      className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold ml-auto shadow-md hover:bg-sepri-dark transition-all active:scale-95"
                    >
                      {currentNews.id ? "Guardar Cambios" : "Publicar Noticia"}
                    </button>
                    <button 
                      type="button" 
                      onClick={() => { setIsEditingNews(false); setCurrentNews({}); }} 
                      className="px-4 py-2 text-gray-500 font-medium hover:text-gray-700"
                    >
                      Cancelar
                    </button>
                 </div>
              </form>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {news.map(n => (
                 <div key={n.id} className="bg-white p-4 rounded-xl border flex gap-4 items-center group hover:border-sepri-medium transition-colors">
                    <div className="w-16 h-16 bg-gray-100 rounded overflow-hidden flex-shrink-0">
                       {n.imageUrl && <img src={n.imageUrl} className="w-full h-full object-cover" />}
                    </div>
                    <div className="flex-1">
                       <h4 className="font-bold text-sm line-clamp-1">{n.title}</h4>
                       <p className="text-xs text-gray-400">{n.date}</p>
                    </div>
                    <div className="flex gap-1">
                       <button onClick={() => { setCurrentNews(n); setIsEditingNews(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded" title="Editar noticia"><Edit2 size={16}/></button>
                       <button onClick={() => handleDeleteNews(n.id)} className="text-red-400 p-2 hover:bg-red-50 rounded" title="Eliminar noticia"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Protocols Tab */}
        {activeTab === 'protocols' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
               <h2 className="text-2xl font-bold">Gestión de Protocolos</h2>
               <button onClick={() => { setCurrentProtocol({ baseSteps: [], questions: [], alerts: [] }); setIsEditingProtocol(true); }} className="bg-sepri-medium text-white px-4 py-2 rounded flex items-center gap-2 hover:bg-sepri-dark">
                  <Plus size={18} /> Nuevo Protocolo
               </button>
            </div>
            {isEditingProtocol && (
               <div className="bg-white p-6 rounded-xl shadow border mb-8 animate-fade-in">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                     <input type="text" placeholder="Título del Protocolo" className="border p-2 rounded" value={currentProtocol.title || ''} onChange={e => setCurrentProtocol({...currentProtocol, title: e.target.value})} />
                     <input type="text" placeholder="Icono (Lucide name)" className="border p-2 rounded" value={currentProtocol.iconName || ''} onChange={e => setCurrentProtocol({...currentProtocol, iconName: e.target.value})} />
                  </div>
                  <textarea placeholder="Descripción corta..." className="w-full border p-2 rounded mb-4" rows={2} value={currentProtocol.description || ''} onChange={e => setCurrentProtocol({...currentProtocol, description: e.target.value})} />
                  <div className="mb-4">
                     <label className="block text-xs font-bold mb-1">URL Documento General</label>
                     <input type="text" placeholder="https://..." className="w-full border p-2 rounded" value={currentProtocol.documentUrl || ''} onChange={e => setCurrentProtocol({...currentProtocol, documentUrl: e.target.value})} />
                  </div>
                  <div className="flex items-center gap-4 mb-6">
                    <div className="w-16 h-16 border rounded bg-gray-50 flex items-center justify-center">
                       {currentProtocol.imageUrl ? <img src={currentProtocol.imageUrl} className="w-full h-full object-cover" /> : <ImageIcon size={20} className="text-gray-300"/>}
                    </div>
                    <label className="bg-gray-100 px-3 py-1 text-xs rounded cursor-pointer border hover:bg-gray-200">
                       Subir Imagen Decorativa
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'protocol')} />
                    </label>
                  </div>
                  <div className="flex gap-4">
                     <button onClick={handleSaveProtocol} className="bg-sepri-medium text-white px-6 py-2 rounded-lg font-bold">Guardar Protocolo</button>
                     <button onClick={() => setIsEditingProtocol(false)} className="px-4 py-2 text-gray-500">Cancelar</button>
                  </div>
               </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               {events.map(event => (
                 <div key={event.id} className="bg-white p-4 rounded-xl border shadow-sm">
                    <h3 className="font-bold">{event.title}</h3>
                    <div className="flex justify-end gap-2 mt-4">
                       <button onClick={() => { setCurrentProtocol(event); setIsEditingProtocol(true); }} className="text-blue-500"><Edit2 size={16}/></button>
                       <button onClick={() => deleteEvent(event.id).then(loadData)} className="text-red-500"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* Configuration Tab */}
        {activeTab === 'config' && (
          <div className="max-w-4xl space-y-10 pb-20">
            <h2 className="text-3xl font-black text-sepri-dark border-b pb-4">Configuración del Sistema</h2>

            {/* Logo & Branding */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><ImageIcon size={20}/> Identidad Visual (Logo D22)</h3>
              <div className="flex items-center gap-6">
                 <div className="w-24 h-24 border rounded-xl overflow-hidden flex items-center justify-center bg-gray-50">
                    {contactInfo.logoUrl ? <img src={contactInfo.logoUrl} className="max-w-full max-h-full object-contain" /> : <ImageIcon className="text-gray-300" size={32}/>}
                 </div>
                 <label className="bg-sepri-bg text-sepri-dark px-4 py-2 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-sm">
                   Subir Logo Distrito
                   <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'logo')} />
                 </label>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
