    if (!id) {
      console.error("Error: ID de aviso no definido");
      return;
    }

    if (!confirm("¿Eliminar este aviso definitivamente?")) return;

    try {
      // Usamos actualización funcional para garantizar que trabajamos con el estado más reciente
      setPopups(prevPopups => {
        const updatedList = prevPopups.filter(p => p.id !== id);

