                    </div>
                    <div>
                       <p className="text-xs font-bold text-gray-500 mb-2 uppercase">Imagen Hero (Inicio)</p>
                       <label className="bg-sepri-bg text-sepri-dark px-3 py-1.5 rounded-lg cursor-pointer hover:bg-gray-200 font-bold text-xs inline-block">
                         Subir Imagen Hero
                         <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'hero')} />
                       </label>
                    </div>
                 </div>
              </div>
            </section>

            {/* Contacts & General Info */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Phone size={20}/> Información de Contacto</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Coordinador Principal</label>
                    <input type="text" placeholder="Nombre Coordinador" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorName || ''} onChange={e => setContactInfo({...contactInfo, coordinatorName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.coordinatorPhone || ''} onChange={e => setContactInfo({...contactInfo, coordinatorPhone: e.target.value})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-500 uppercase">Asistente de Coordinación</label>
                    <input type="text" placeholder="Nombre Asistente" className="w-full border p-3 rounded-lg" value={contactInfo.assistantName || ''} onChange={e => setContactInfo({...contactInfo, assistantName: e.target.value})} />
                    <input type="text" placeholder="Teléfono" className="w-full border p-3 rounded-lg" value={contactInfo.assistantPhone || ''} onChange={e => setContactInfo({...contactInfo, assistantPhone: e.target.value})} />
                 </div>
              </div>
              <div className="space-y-4">
                 <input type="email" placeholder="email@ipuc.org.co" className="w-full border p-3 rounded-lg" value={contactInfo.email || ''} onChange={e => setContactInfo({...contactInfo, email: e.target.value})} />
                 <input type="text" placeholder="Dirección Administrativa" className="w-full border p-3 rounded-lg" value={contactInfo.address || ''} onChange={e => setContactInfo({...contactInfo, address: e.target.value})} />
              </div>
            </section>

            {/* Social Media */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Facebook size={20}/> Redes Sociales</h3>
              <div className="space-y-4">
                 <div className="flex items-center gap-4">
                    <Facebook className="text-blue-600" />
                    <input type="text" placeholder="URL Facebook" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.facebookUrl || ''} onChange={e => setContactInfo({...contactInfo, facebookUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Instagram className="text-pink-600" />
                    <input type="text" placeholder="URL Instagram" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.instagramUrl || ''} onChange={e => setContactInfo({...contactInfo, instagramUrl: e.target.value})} />
                 </div>
                 <div className="flex items-center gap-4">
                    <Youtube className="text-red-600" />
                    <input type="text" placeholder="URL YouTube" className="flex-1 border p-3 rounded-lg text-sm" value={contactInfo.youtubeUrl || ''} onChange={e => setContactInfo({...contactInfo, youtubeUrl: e.target.value})} />
                 </div>
              </div>
            </section>

            {/* Quick Links Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><LinkIcon size={20}/> Enlaces Rápidos (Footer)</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-3">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del enlace" className="border p-2 rounded text-sm" value={newQuickLink.title || ''} onChange={e => setNewQuickLink({...newQuickLink, title: e.target.value})} />
                    <input type="text" placeholder="URL (/ruta o https://)" className="border p-2 rounded text-sm" value={newQuickLink.url || ''} onChange={e => setNewQuickLink({...newQuickLink, url: e.target.value})} />
                 </div>
                 <button onClick={handleAddQuickLink} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold hover:bg-sepri-dark">Agregar Enlace</button>
              </div>
              <div className="space-y-2">
                 {quickLinks.map(link => (
                    <div key={link.id} className="flex items-center justify-between p-3 border rounded-lg bg-white">
                       <div className="flex items-center gap-3">
                          <input type="checkbox" checked={link.isEnabled} onChange={() => handleToggleQuickLink(link.id)} className="w-4 h-4 accent-sepri-medium" />
                          <div>
                             <p className="text-sm font-bold">{link.title}</p>
                             <p className="text-[10px] text-gray-500">{link.url}</p>
                          </div>
                       </div>
                       <button onClick={() => handleRemoveQuickLink(link.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* Popups Manager */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Bell size={20}/> Ventanas Emergentes (Popups)</h3>

              <div className="bg-gray-50 p-6 rounded-xl space-y-4 border border-blue-100">
                 <h4 className="font-bold text-sm text-sepri-dark flex items-center gap-2">
                   {currentPopup.id ? <Edit2 size={16}/> : <Plus size={16}/>}
                   {currentPopup.id ? "Editar Aviso" : "Crear Nuevo Aviso"}
                 </h4>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <input type="text" placeholder="Título del aviso" className="border p-2 rounded text-sm focus:ring-2 focus:ring-sepri-medium outline-none" value={currentPopup.title || ''} onChange={e => setCurrentPopup({...currentPopup, title: e.target.value})} />
                    <select className="border p-2 rounded text-sm outline-none" value={currentPopup.type || 'info'} onChange={e => setCurrentPopup({...currentPopup, type: e.target.value as any})}>
                       <option value="info">Información (Azul)</option>
                       <option value="warning">Advertencia (Amarillo)</option>
                       <option value="alert">Alerta Crítica (Rojo)</option>
                    </select>
                 </div>
                 <textarea placeholder="Contenido del mensaje..." className="w-full border p-2 rounded text-sm focus:ring-2 focus:ring-sepri-medium outline-none" rows={3} value={currentPopup.content || ''} onChange={e => setCurrentPopup({...currentPopup, content: e.target.value})} />
                 <div className="flex gap-2 justify-end">
                    {currentPopup.id && (
                      <button onClick={() => setCurrentPopup({ title: '', content: '', type: 'info', isEnabled: true })} className="px-4 py-2 text-xs font-bold text-gray-500 hover:text-gray-700">Cancelar</button>
                    )}
                    <button onClick={(e) => { e.preventDefault(); handleSavePopup(); }} className="bg-sepri-medium text-white px-6 py-2 rounded-lg text-xs font-bold hover:bg-sepri-dark shadow-md flex items-center gap-2">
                      <Save size={14}/> {currentPopup.id ? "Actualizar Aviso" : "Crear Aviso"}
                    </button>
                 </div>
              </div>

              <div className="space-y-3">
                 <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest px-1">Avisos Activos en el Sistema</h4>
                 {popups.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border rounded-xl bg-white shadow-sm hover:border-sepri-medium transition-colors group">
                       <div className="flex items-center gap-4">
                          <input type="checkbox" checked={p.isEnabled} onChange={(e) => { e.stopPropagation(); handleTogglePopup(p.id); }} className="w-5 h-5 accent-sepri-medium cursor-pointer" />
                          <div>
                             <div className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${p.type === 'alert' ? 'bg-red-500' : p.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'}`}></span>
                                <p className="text-sm font-bold text-sepri-dark">{p.title}</p>
                             </div>
                             <p className="text-xs text-gray-500 line-clamp-1">{p.content}</p>
                          </div>
                       </div>
                       <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => setCurrentPopup(p)} className="text-blue-500 p-2 hover:bg-blue-50 rounded"><Edit2 size={16}/></button>
                          <button onClick={(e) => handleRemovePopup(p.id, e)} className="text-red-400 p-2 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                       </div>
                    </div>
                 ))}
                 {popups.length === 0 && <p className="text-center py-8 text-gray-400 italic text-sm border-2 border-dashed rounded-xl">No hay avisos configurados.</p>}
              </div>
            </section>

            {/* Privacy Policy */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><Lock size={20}/> Políticas y Privacidad</h3>
              <textarea 
                className="w-full border p-4 rounded-xl min-h-[150px] text-sm leading-relaxed" 
                value={contactInfo.privacyPolicy || ''} 
                onChange={e => setContactInfo({...contactInfo, privacyPolicy: e.target.value})}
                placeholder="Escribe la política de privacidad oficial aquí..."
              />
            </section>

            {/* Team Members */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border space-y-6">
              <h3 className="font-bold text-lg flex items-center gap-2 text-sepri-medium"><User size={20}/> Equipo SEPRI</h3>
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <input type="text" placeholder="Nombre" className="border p-2 rounded text-sm" value={newMember.name || ''} onChange={e => setNewMember({...newMember, name: e.target.value})} />
                    <input type="text" placeholder="Cargo" className="border p-2 rounded text-sm" value={newMember.role || ''} onChange={e => setNewMember({...newMember, role: e.target.value})} />
                 </div>
                 <div className="flex gap-4">
                    <label className="bg-white px-4 py-2 border rounded cursor-pointer text-xs font-bold">
                       {newMember.imageUrl ? "Foto lista" : "Subir Foto"}
                       <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member')} />
                    </label>
                    <button onClick={handleAddMember} className="bg-sepri-medium text-white px-4 py-2 rounded text-xs font-bold ml-auto">Agregar Miembro</button>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {contactInfo.teamMembers?.map(m => (
                    <div key={m.id} className="flex items-center gap-4 p-3 border rounded-xl bg-white shadow-sm group">
                       <div className="w-12 h-12 rounded-full bg-gray-100 overflow-hidden relative flex-shrink-0 group/img">
                          {m.imageUrl ? <img src={m.imageUrl} className="w-full h-full object-cover" /> : <User size={20} className="m-auto text-gray-300 h-full" />}
                          <label className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center cursor-pointer">
                             <Plus size={14} className="text-white" />
                             <input type="file" className="hidden" onChange={e => handleImageUpload(e, 'member', m.id)} />
                          </label>
                       </div>
                       <div className="flex-1">
                          <p className="font-bold text-xs">{m.name}</p>
                          <p className="text-[10px] text-gray-500">{m.role}</p>
                       </div>
                       <button onClick={() => handleRemoveMember(m.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                 ))}
              </div>
            </section>

            {/* GLOBAL SAVE ACTION */}
            <div className="sticky bottom-6 flex justify-center">
               <button onClick={handleSaveConfig} className="bg-green-600 text-white px-12 py-4 rounded-full font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-green-700 transition-all hover:scale-105 active:scale-95 group">
                 <Save size={24} className="group-hover:rotate-12 transition-transform"/> GUARDAR TODA LA CONFIGURACIÓN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLogin;

