                       <input type="checkbox" className="h-6 w-6 accent-sepri-medium" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.checked ? 'Si' : 'No'})} />
                       <span className="text-sm font-bold text-gray-700">Confirmar cumplimiento</span>
                     </div>
                   ) : (
                     <input type="text" className="w-full bg-gray-50 border p-4 rounded-2xl outline-none focus:ring-2 focus:ring-sepri-medium" onChange={(e) => setFormResponses({...formResponses, [field.id]: e.target.value})} />
                   )}
                 </div>
               ))}
             </div>

             <div className="mt-10 flex gap-4">
               <button onClick={() => setActiveForm(null)} className="flex-1 px-6 py-4 text-gray-400 font-black text-xs uppercase tracking-widest">Cerrar</button>
               <button onClick={handleDownloadForm} className="flex-[2] bg-sepri-dark text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-sepri-medium transition-all shadow-xl">
                 GENERAR Y DESCARGAR
               </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

