"use client"
import React, { useEffect, useRef, useState } from "react"
import { MeshGradient, PulsingBorder } from "@paper-design/shaders-react"
import { motion } from "framer-motion"
import { ShieldCheck, AlertTriangle, ChevronRight } from "lucide-react"
import { Link } from "react-router-dom"

export default function ShaderHero() {
  const containerRef = useRef<HTMLDivElement>(null)
  const [isActive, setIsActive] = useState(false)

  useEffect(() => {
    const handleMouseEnter = () => setIsActive(true)
    const handleMouseLeave = () => setIsActive(false)

    const container = containerRef.current
    if (container) {
      container.addEventListener("mouseenter", handleMouseEnter)
      container.addEventListener("mouseleave", handleMouseLeave)
    }

    return () => {
      if (container) {
        container.removeEventListener("mouseenter", handleMouseEnter)
        container.removeEventListener("mouseleave", handleMouseLeave)
      }
    }
  }, [])

  // Robust rendering for components that might fail to load from external ESM
  const SafeMeshGradient = (props: any) => {
    try {
      return MeshGradient ? <MeshGradient {...props} /> : <div className="absolute inset-0 bg-sepri-dark" />;
    } catch (e) {
      return <div className="absolute inset-0 bg-sepri-dark" />;
    }
  };

  const SafePulsingBorder = (props: any) => {
    try {
      return PulsingBorder ? <PulsingBorder {...props} /> : <div className="w-20 h-20 rounded-full border border-sepri-yellow" />;
    } catch (e) {
      return <div className="w-20 h-20 rounded-full border border-sepri-yellow" />;
    }
  };

  return (
    <div ref={containerRef} className="relative min-h-[85vh] md:min-h-screen bg-sepri-dark overflow-hidden flex flex-col">
      <svg className="absolute inset-0 w-0 h-0">
        <defs>
          <filter id="glass-effect" x="-50%" y="-50%" width="200%" height="200%">
            <feTurbulence baseFrequency="0.005" numOctaves="1" result="noise" />
            <feDisplacementMap in="SourceGraphic" in2="noise" scale="0.3" />
            <feColorMatrix
              type="matrix"
              values="1 0 0 0 0.05
                      0 1 0 0 0.16
                      0 0 1 0 0.28
                      0 0 0 0.9 0"
              result="tint"
            />
          </filter>
          <filter id="logo-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="4" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <linearGradient id="sepri-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#FFB000" />
            <stop offset="50%" stopColor="#ffffff" />
            <stop offset="100%" stopColor="#FFB000" />
          </linearGradient>
        </defs>
      </svg>

      {/* Mesh Gradients - SEPRI Palette */}
      <SafeMeshGradient
        className="absolute inset-0 w-full h-full"
        colors={["#0E2A47", "#164E87", "#0B1D33", "#164E87", "#FFB000"]}
        speed={0.2}
        backgroundColor="#0E2A47"
      />
      <SafeMeshGradient
        className="absolute inset-0 w-full h-full opacity-30"
        colors={["#ffffff", "#FFB000", "#164E87", "#0E2A47"]}
        speed={0.15}
        wireframe="true"
        backgroundColor="transparent"
      />

      <header className="relative z-30 flex items-center justify-between p-6 md:px-12">
        <motion.div
          className="flex items-center group cursor-pointer"
          whileHover={{ scale: 1.05 }}
          transition={{ type: "spring", stiffness: 400, damping: 10 }}
        >
          <div className="relative" style={{ filter: "url(#logo-glow)" }}>
            <ShieldCheck className="w-10 h-10 text-sepri-yellow" />
            <div className="absolute inset-0 bg-sepri-yellow/20 blur-xl rounded-full group-hover:bg-white/40 transition-colors duration-500"></div>
          </div>
          <div className="ml-3 flex flex-col leading-none">
            <span className="text-white font-black text-2xl tracking-tighter uppercase">SEPRI</span>
            <span className="text-sepri-yellow font-bold text-[10px] tracking-[0.3em] uppercase">Distrito 22</span>
          </div>
        </motion.div>

        {/* Action Buttons */}
        <div className="hidden md:flex items-center gap-4">
          <Link
            to="/formatos"
            className="text-white/80 hover:text-white text-xs font-bold uppercase tracking-widest px-4 py-2 rounded-full hover:bg-white/10 transition-all"
          >
            Formatos
          </Link>
          <Link
            to="/admin"
